=== file: main.loom ===
budget { tokens: 4000 calls: 4 }

tool translate { use: translate }
tool file { use: file root: "translations" mode: write }

agent Translator {
    model: "gpt-6-luna"
    prompt: "translator"
    tools: [translate]
    approve: [translate]
    temperature: 0.2
    output_schema: { french: string, spanish: string }
}

agent Saver {
    model: "gpt-6-luna"
    prompt: "saver"
    tools: [file]
    approve: [file]
    temperature: 0.1
    output_schema: { saved: enum["YES"] }
}

workflow Main(catalogue_copy, destination_filename) {
    human_prompt "ProductOwner: May this product description be sent to the approved external translation provider? Reply YES or NO." -> provider_consent expecting { decision: enum["YES", "NO"] }

    alt (provider_consent.decision == "YES") {
        delegate "Translate this product description faithfully into French and Spanish. Use the approved translate tool. Return both complete translations in the required structured format.\n\nDescription:\n{catalogue_copy}" to Translator -> translation_bundle expecting { french: string, spanish: string } retry 1 backoff 2s timeout 30s on_failure {
            halt "Translation failed; no file was written."
        }

        human_prompt "ProductOwner: Review these translations and approve or reject saving them as UTF-8.\n\nFrench:\n{translation_bundle.french}\n\nSpanish:\n{translation_bundle.spanish}\n\nReply YES or NO." -> save_consent expecting { decision: enum["YES", "NO"] }

        alt (save_consent.decision == "YES") {
            delegate "Save both approved translations unchanged as UTF-8 in one file named {destination_filename}, beneath the configured translations output directory. Write the French translation, then the Spanish translation, with clear language labels. Report saved YES only after the file tool confirms the write.\n\nFrench:\n{translation_bundle.french}\n\nSpanish:\n{translation_bundle.spanish}" to Saver -> save_receipt expecting { saved: enum["YES"] } retry 1 backoff 2s timeout 30s on_failure {
                halt "File writing failed; the translations were not reported as saved."
            }
            return "Both approved translations were saved as UTF-8."
        } else {
            halt "The ProductOwner rejected saving; no file was written."
        }
    } else {
        halt "The ProductOwner did not approve external translation; the provider was not called and no file was written."
    }
}
=== end ===
